import json,numpy as np
s=json.load(open('/app/runs/clean_up_toys/spec.json'))
for cam in ['egocentric_mirrored_camera','over_shoulder_left_camera']:
 c=s['cameras'][cam]
 K=np.array(c['intrinsic_cv']); E=np.array(c['extrinsic_cv']); R=E[:,:3]; t=E[:,3]; o=-R.T@t
 print(cam,'origin',o)
 def intersect(u,v,z=0.003):
  d=R.T@np.linalg.inv(K)@np.array([u,v,1.]); return o+(z-o[2])/d[2]*d
 if cam.startswith('ego'):
  for name,p in {'bin':(278,180),'cube1':(448,163),'cube2':(448,216),'cube3':(559,183),'blue':(481,177),'green':(717,180),'yellow':(692,143),'red':(592,231),'lizard1':(666,172),'lizard2':(486,278),'bird':(695,342)}.items(): print(name,intersect(*p)[:2])
PY

